function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Find all menu sections that contain a user-items-list
  $('#sections section.page-section').each((_, sectionEl) => {
    const $section = $(sectionEl);
    const $list = $section.find('.user-items-list').first();
    if (!$list) return;

    // Get section title from list-section-title
    const $sectionTitleEl = $list.find('.list-section-title strong, .list-section-title p strong').first();
    const section = $sectionTitleEl ? cleanText($sectionTitleEl.text()) : null;

    // Iterate over each menu item
    $list.find('ul.user-items-list-simple > li.list-item').each((_, itemEl) => {
      const $item = $(itemEl);

      // Name from h2.list-item-content__title
      const $titleEl = $item.find('h2.list-item-content__title').first();
      if (!$titleEl) return;
      let name = cleanText($titleEl.text());
      if (!name) return;

      // Clean leading numbering and trailing allergen codes
      name = name.replace(/^\d+[\.\s]+/, '').replace(/\s*\([\d,\s]+\)\s*$/, '').trim();
      if (!name) return;

      // Description: first p in list-item-content__description that doesn't contain only the price
      const $descWrapper = $item.find('.list-item-content__description').first();
      let description = null;
      if ($descWrapper) {
        const $descParagraphs = $descWrapper.find('p');
        for (let i = 0; i < $descParagraphs.length; i++) {
          const $p = $($descParagraphs[i]);
          const text = cleanText($p.text());
          // Skip if this paragraph only contains a price (strong with price pattern)
          const $strong = $p.find('strong').first();
          if ($strong && /^[\d\s.,-]+$/.test(cleanText($strong.text()))) continue;
          if (text) {
            description = text;
            break;
          }
        }
      }

      // Price: find strong tag with price in description wrapper
      let price = null;
      if ($descWrapper) {
        const $priceStrong = $descWrapper.find('strong').first();
        if ($priceStrong) {
          price = parsePrice($priceStrong.text());
        }
      }

      // Deduplicate
      const key = `${section}|${name}|${description || ''}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
